import pages as PG
from pages import *
from fig2 import *
from fig import strip,svg
P_=[('overview','Kārtika Māsa','The Month of Lamps'),('damodarashtakam','The Dāmodarāṣṭakam','Kṛṣṇa Bound with a Rope'),('somavara-lakshadipotsava','Kārtika Somavāras','Śiva’s Mondays and the Lakṣa Dīpotsava'),('karthigai-deepam','Kārttikai Dīpam','The Flame on Aruṇācala'),('tulasi','Tulasī','The Sacred Plant in the Courtyard'),('prabodhini-tulasi-vivaha','Prabodhinī and Tulasī Vivāha','Viṣṇu Wakes, Tulasī Weds'),('kartika-purnima','Kārtika Pūrṇimā','Tripurāri and the River of Lamps')]
PG.configure('/festivals/kartika/',P_,'navy','Kārtika Māsa','Lord','Kārtika')
PG.OUT='outx/kartika/'
import pages
L=pages.link
DAM=[l.strip() for l in open('dam.txt').read().strip().split('\n')]
def V(): return vishnu()
def kr_rope(): return krishna_child()+'<path d="M-10 -8 q-20 4 -30 14" fill="none" stroke="#a8553a" stroke-width="3"/>'+'<g transform="translate(-40 14)">'+mortar()+'</g>'
def yashoda(): return person('#c0392b')+'<g transform="translate(14 -24) rotate(30)"><path d="M0 0 v-30" stroke="#8a5a2a" stroke-width="3"/></g>'
def lamps_row(n=7,w=440,y=0): return ''.join(f'<g transform="translate({(k+.5)*w/n} {y})">{lamp(["#c0392b","#e0a800","#1d6fb8"][k%3])}</g>' for k in range(n))
# ---------- Part 1
i=0
COV=covart('A row of oil lamps along a riverbank at dawn, a devotee bathing, and the child Kṛṣṇa tied to a mortar',river(440,150)+g(220,140,1,lamps_row(9,400))+g(110,150,1,person('#c0392b'))+g(350,196,1.2,kr_rope()))
pp=[foreword(i,['After Dīpāvalī comes a whole month of lamps. <b>Kārtika</b>, the eighth lunar month, is counted by many traditions as the holiest month of the year, dear to both Viṣṇu and Śiva. People rise before dawn to bathe, light lamps at temples and riverbanks, and keep vows through the month.','This 7-part series covers Kārtika: the month itself, its great hymn the <b>Dāmodarāṣṭakam</b>, Śiva’s Mondays and Karnataka’s lamp festivals, the <b>Kārttikai Dīpam</b> of Tiruvaṇṇāmalai, <b>Tulasī</b> and her wedding, and <b>Kārtika Pūrṇimā</b>.'],[('z','A whole month of festival?'),('b','A whole month of light. Every evening is a small Dīpāvalī.')]),
 glance([('Month','Kārtika, the eighth lunar month (October–November)'),('Begins','After Dīpāvalī (in the amānta, new-moon-ending calendar)'),('Dear to','Viṣṇu as Dāmodara, and Śiva'),('Practices','Dawn bath (Kārtika snāna), lamps (dīpa-dāna), hanging sky-lamps, tulasī worship'),('Great days','Kārtika Somavāras; Prabodhinī Ekādaśī and Tulasī Vivāha; Kārtika Pūrṇimā; Kārttikai Dīpam'),('Hymn','The Dāmodarāṣṭakam (Padma Purāṇa)'),('Ends','With the new moon; Mārgaśīrṣa follows')],svg(560,140,'A row of lamps',g(280,110,1,lamps_row(9,500)))),
 reading('holiest','THE HOLIEST MONTH','Why Kārtika is special',svg(560,170,'Viṣṇu and Śiva side by side with lamps between them',g(180,160,1,V())+g(380,160,1,shiva())+g(280,150,1.4,lamp())),['<b>Praised in the Purāṇas.</b> The Skanda and Padma Purāṇas praise Kārtika above all months; a popular verse says there is no month like Kārtika, no age like Satya, no scripture like the Veda.','<b>For Viṣṇu.</b> Vaiṣṇavas worship Kṛṣṇa as <b>Dāmodara</b>, “the one with a rope round his belly”, through the month (Part 2).','<b>For Śiva.</b> Śaivas keep its Mondays (<b>Somavāras</b>) and light lamps in Śiva temples (Part 3); Kārtika Pūrṇimā celebrates his victory over the three cities (Part 7).','<b>For both.</b> The month joins the two traditions in one practice: light offered in the dark of the year.'],[('z','So both Śaivas and Vaiṣṇavas love it?'),('b','It is one of the few months both claim with equal joy.')],'Kārtika: <b>the month both Viṣṇu and Śiva share</b>.'),
 reading('dawn','THE DAWN BATH','Kārtika snāna',svg(560,170,'Devotees bathing in a river before sunrise with the morning star above',river(560,110)+g(220,140,1,person('#c0392b'))+g(320,140,1,person('#1d6fb8'))+'<circle cx="460" cy="30" r="4" fill="#fff8d0"/>',bg='#2a2a3a'),['<b>Before sunrise.</b> Throughout Kārtika many devotees bathe before dawn, ideally in a river or tank, reciting the names of God.','<b>Why dawn.</b> The hour before sunrise (brāhma muhūrta) is counted as the purest; in the cold of early winter the bath is also a discipline.','<b>At home.</b> Those who cannot reach a river bathe at home, with a prayer remembering the sacred rivers.','<b>Then the lamp.</b> After the bath, a lamp is lit at the tulasī or the home shrine.'],[('z','In the cold?'),('b','That is part of it. A small hardship, cheerfully offered.')],'Up before dawn, <b>bathe, pray, light a lamp</b>.'),
 reading('lamps','GIVING LIGHT','Dīpa-dāna and the sky lamp',svg(560,190,'A lamp hung high on a bamboo pole against the night sky, and lamps lit in a row on a temple wall','<rect width="560" height="190" fill="#2a2a3a"/>'+'<path d="M120 190 v-150" stroke="#c9a24a" stroke-width="5"/>'+g(120,44,1,'<path d="M-14 0 h28 l-4 16 h-20z" fill="#e0a800" stroke="#111"/>'+lamp())+g(380,150,1,lamps_row(7,280))+lab(120,180,'ākāśa dīpa',11)),['<b>Dīpa-dāna.</b> The central practice of the month is the gift of light: lamps offered to Viṣṇu, Śiva, the tulasī, temples, riverbanks and crossroads.','<b>The sky lamp.</b> Many homes hang an <b>ākāśa dīpa</b>, a lamp raised high on a pole, every evening of the month, said to light the way for departed ancestors.','<b>Temples.</b> Temples across Karnataka hold <b>dīpotsavas</b>, festivals of thousands of lamps, through the month (Part 3).','<b>Why light.</b> Light in the dark half of the year is the simplest prayer: may there be light, outside and within.'],[('z','Lamps for the ancestors?'),('b','So the tradition says: the high lamp shows them the way. It is also a lovely way to remember them.')],'Light given every evening: <b>dīpa-dāna</b>.'),
 reading('vows','VOWS OF THE MONTH','Kārtika vrata',svg(560,160,'A simple meal, a book and a rosary representing the month’s vows',g(140,130,1.3,'<ellipse rx="40" ry="10" fill="#5a8a3a"/>')+g(280,130,1.4,book())+g(420,120,1.6,rosary())),['<b>Simple living.</b> Many keep a vow for the month: eating once a day, avoiding certain foods, sleeping on the floor, or reading a scripture daily.','<b>Reading.</b> The Bhāgavatam, the Gītā, the Kārtika Māhātmya or the Dāmodarāṣṭakam are read daily.','<b>Charity.</b> Giving lamps, food and warm clothing in the coming cold is praised.','<b>Cāturmāsya ends.</b> The four-month vows taken on Devaśayanī are completed on Prabodhinī Ekādaśī in this month ('+L(5,'Part 6')+'; see also our <a href="/festivals/ekadashi/">Ekādaśī series</a>).'],[('z','Which vow should I take?'),('b','One you can keep for thirty days. A lamp every evening is a perfect start.')],'A small vow kept <b>every day of the month</b>.'),
 end(i,['<b>Month.</b> Kārtika, the holiest month, after Dīpāvalī.','<b>Both gods.</b> Dāmodara for Vaiṣṇavas, Śiva’s Mondays for Śaivas.','<b>Dawn.</b> The Kārtika bath before sunrise.','<b>Light.</b> Dīpa-dāna and the sky lamp.','<b>Vows.</b> Simple living, reading, charity.'],'Part 2 sings the month’s great hymn, the Dāmodarāṣṭakam, verse by verse.','Kārtika Māsa'),
 sources([('Month:','Wikipedia, “Kartika (month)”, “Kartik Snan”, “Akasha Deepa”; Skanda Purāṇa, Vaiṣṇava Khaṇḍa (Kārtika Māsa Māhātmya) as commonly cited.')],'the popular verse ranking months (cited from the Skanda Purāṇa; wording varies); regional dates (amānta vs pūrṇimānta).','Customs described in their common forms.')]
build(i,'PART 1 OF 7 · DAWN · LAMPS · VOWS',COV,'The month of lamps','<b>Why Kārtika</b> is the holiest month, the <b>dawn bath</b>, <b>giving light</b> and the sky lamp, and the vows of the month.','Kārtika Māsa explained: why it is the holiest month for Viṣṇu and Śiva, the dawn bath, dīpa-dāna and the ākāśa dīpa, and the month’s vows. Part 1 of the illustrated Kārtika series.',pp)
# ---------- Part 2 Dāmodarāṣṭakam
i=1
COV=covart('Yaśodā holding a stick and a rope, the child Kṛṣṇa tied to a wooden mortar crying, two tall trees behind',g(130,196,1.3,yashoda())+g(260,196,1.3,kr_rope())+g(380,196,1.2,tree())+g(420,196,1.1,tree()))
M=[('THE LORD WHO RAN FROM HIS MOTHER','I bow to the Lord whose form is being, awareness and bliss, his earrings swinging, shining in Gokula; who ran from the mortar in fear of Yaśodā, and was caught from behind by the cowherd woman, running faster still.',[('īśvaram','the Lord'),('sac-cid-ānanda-rūpam','whose form is being, awareness and bliss'),('lasat-kuṇḍalam','with swinging earrings'),('ulūkhale','from the mortar'),('parāmṛṣṭam','caught')],'<b>God, caught.</b> The very first line calls him the Lord of existence and bliss; the next lines show him running from his mother and caught. That contrast is the whole hymn.'),
 ('TEARS OF A CHILD','He cries again and again, rubbing his two eyes with his lotus hands, eyes full of fear; sobbing, the lines of the necklace on his throat trembling, bound by love. I praise Dāmodara, worshipped by his devotees.',[('rudantam','crying'),('mṛjantam','rubbing'),('sātaṅka-netram','with frightened eyes'),('muhuḥ-śvāsakam','sobbing again and again'),('bhakta-vandyam','worshipped by devotees')],'<b>A real child.</b> The verse lingers on tiny details: hands rubbing eyes, catching breath. The poet wants us to see God as a frightened little boy, and love him.'),
 ('NOT EVEN LIBERATION','O Lord, giver of boons, I do not ask you for liberation, or for the highest goal, or any other boon. May this form of yours, the cowherd child, always appear in my mind. What use are other things?',[('varam','a boon'),('mokṣa-avadhim','liberation, the final goal'),('na anyam vṛṇe','I choose nothing else'),('gopāla-bālam','the cowherd boy'),('āvirāstām','may it appear')],'<b>The famous refusal.</b> The devotee turns down even liberation. All he wants is to keep seeing the child Kṛṣṇa in his heart: love for its own sake.'),
 ('THE FACE KISSED BY HIS MOTHER','May this lotus face of yours, framed by dark, glossy curls, its lips red as the bimba fruit, kissed again and again by the cowherd mother, appear in my mind. Enough of a hundred thousand other gains!',[('mukha-ambhojam','lotus face'),('kuntalaiḥ','with curls'),('cumbitam','kissed'),('bimba-rakta-adharam','lips red as the bimba fruit'),('alam lakṣa-lābhaiḥ','enough of countless gains')],'<b>Through her eyes.</b> We see Kṛṣṇa as Yaśodā sees him: a face to kiss. The devotee asks to love him the way a mother does.'),
 ('A PLEA FOR GRACE','Salutations, O Lord Dāmodara, Ananta, Viṣṇu! Be gracious, Master. With the rain of your merciful glance, protect me, drowning in an ocean of sorrows, wretched and ignorant; become visible to my eyes.',[('prasīda','be gracious'),('duḥkha-jāla-abdhi-magnam','drowning in the sea of sorrows'),('kṛpā-dṛṣṭi-vṛṣṭyā','by the rain of your merciful glance'),('rakṣa','protect'),('akṣi-dṛśyam','visible to the eyes')],'<b>From wonder to need.</b> After the tender pictures, the devotee speaks plainly of his own sorrow and asks only to be looked upon with mercy.'),
 ('THE TWO TREES','Just as you freed Kubera’s two sons, who had become trees, and made them your devotees, so grant me your own loving devotion. I have no craving for liberation, Dāmodara.',[('kubera-ātmajau','the two sons of Kubera'),('vṛkṣa-mūrtī','in the form of trees'),('mocitau','freed'),('prema-bhaktim','loving devotion'),('na mokṣe āgrahaḥ','no insistence on liberation')],'<b>The story behind the hymn.</b> Tied to the mortar, little Kṛṣṇa crawled between two arjuna trees and pulled them down, freeing Kubera’s cursed sons, Nalakūbara and Maṇigrīva (Bhāgavatam 10.10). The devotee asks to be freed into love the same way.'),
 ('THE ROPE OF LOVE','Salutations to the rope (dāma) round your belly, shining bright; salutations to your belly, home of the whole universe; salutations to Rādhikā, dear to you; salutations to you, the God of endless play.',[('sudāmne','to the beautiful rope'),('sphurad-dīpta-dhāmne','shining with light'),('udara-stha-viśvasya dhāmne','to the belly that holds the universe'),('rādhikāyai','to Rādhikā'),('ananta-līlāya','whose play is endless')],'<b>The rope and the universe.</b> The same belly that Yaśodā bound holds the whole universe. Only love can bind the infinite: that is the meaning of the name Dāmodara.')]
pp=[foreword(i,['The great hymn of Kārtika is the <b>Dāmodarāṣṭakam</b>, a prayer to the child Kṛṣṇa tied with a rope (<i>dāma</i>) round his belly (<i>udara</i>). The Padma Purāṇa gives it to the sage <b>Satyavrata</b>, who sang it while worshipping Dāmodara in Kārtika at Vṛndāvana.','Vaiṣṇavas, especially in the Gauḍīya tradition, sing it every evening of the month while offering a lamp. Here is the story behind it and every verse, with its meaning.'],[('z','Why tie God up?'),('b','His mother did, because he was naughty! The hymn says only love could ever bind him.')]),
 glance([('Name','Dāmodarāṣṭakam: “eight verses on Dāmodara”'),('Source','Padma Purāṇa, sung by the sage Satyavrata (Rukmāṅgada–Mohinī dialogue)'),('Story','Bhāgavata Purāṇa 10.9–10: Yaśodā binds Kṛṣṇa; the two arjuna trees'),('Sung','Every evening of Kārtika with a lamp'),('Theme','Love for the child Kṛṣṇa, preferred even to liberation'),('Edition','sanskritdocuments.org, Satyavratokta Dāmodarastotram: 7 verses of praise')],svg(560,150,'Kṛṣṇa tied to the mortar between two trees',g(180,140,1,tree())+g(280,140,1.3,kr_rope())+g(380,140,1,tree()))),
 story('binding','THE STORY: YAŚODĀ BINDS KṚṢṆA','Bhāgavata Purāṇa 10.9–10',strip('Three panels: Kṛṣṇa breaking a pot of butter; Yaśodā tying him to a mortar; the mortar pulling down two trees',[panel([(krishna_child(),1.4),(pot('#fff8d0'),1)],'#fff3cf',140),panel([(yashoda(),.9),(kr_rope(),1)],'#cfe0b8',140),panel([(tree(),.7),(kr_rope(),.8),(tree(),.7)],'#dfe9f6',140)],['the butter pot broken','a rope that is always too short','the two trees fall']),'This story is the reason for the name Dāmodara.',['One morning Yaśodā left the churning to tend boiling milk. Little Kṛṣṇa, angry at being put down, broke the butter pot and ran off to feed butter to the monkeys.','Yaśodā chased him with a stick. He ran in fear, but she caught him.','She decided to tie him to the wooden mortar. Every rope was two fingers too short, however many she joined.','Seeing his mother tired and sweating, Kṛṣṇa let himself be tied. So he is <b>Dāmodara</b>, “the one with a rope round his belly”.','Crawling, he dragged the mortar between two arjuna trees and pulled them down; from them stepped Nalakūbara and Maṇigrīva, Kubera’s sons, freed from a curse.'],[('z','Why was the rope always too short?'),('b','You can’t tie up the infinite. He let himself be tied when he saw her love. That is the theology in one picture.')],'Only love could tie the Lord: <b>Dāmodara</b>.')]
for k,(t,mean,words,ins) in enumerate(M):
    pp.append(verse(f'v{k+1}',f'VERSE {k+1}',t,DAM[2*k:2*k+2],svg(220,160,'The child Kṛṣṇa',g(110,150,1.6,kr_rope() if k in (0,1,6) else krishna_child()),cls=''),mean,words,ins,None,['The Lord, caught by love.','Tears of a child; God within reach.','Not even liberation: only this child in my heart.','Love him as his mother does.','Be gracious; look on me.','Free me into love, as you freed the trees.','A rope of love binds the infinite.'][k],'Text: sanskritdocuments.org, Satyavratokta Dāmodarastotram (Padma Purāṇa), hymn verses 5–11 numbered here 1–7.'+(' Many popular editions add a further verse, “itīdṛk svalīlābhir…”; this edition does not include it.' if k==2 else '')))
pp+=[reading('singing','SINGING IT IN KĀRTIKA','The evening lamp',svg(560,170,'A family offering a ghee lamp before a picture of child Kṛṣṇa tied to the mortar, singing',g(280,150,1.2,kr_rope())+g(160,160,1,person('#c0392b',seat=True))+g(400,160,1,person('#1d6fb8',seat=True))+g(220,120,1,lamp())),['<b>Every evening.</b> In the Vaiṣṇava tradition the Dāmodarāṣṭakam is sung each evening of Kārtika while offering a small ghee lamp to Kṛṣṇa as Dāmodara.','<b>Everyone offers.</b> In temples and homes each person, including children, takes a turn offering the lamp, often in a small clay dish.','<b>Simple worship.</b> No elaborate ritual is needed: a lamp, the hymn and love.','<b>Read with meaning.</b> Our IAST guide (<a href="/how-to-read-iast/">How to read IAST</a>) helps with pronunciation.'],[('z','Can children offer the lamp?'),('b','Especially children. It is a hymn about a child.')],'A lamp and the hymn, <b>every evening of Kārtika</b>.'),
 end(i,['<b>Story.</b> Yaśodā bound naughty Kṛṣṇa to a mortar; the rope was always short.','<b>Name.</b> Dāmodara: rope (dāma) round the belly (udara).','<b>Hymn.</b> Satyavrata’s prayer in the Padma Purāṇa.','<b>Heart.</b> Love for the child Kṛṣṇa, preferred even to liberation.','<b>Practice.</b> Sung with a lamp every Kārtika evening.'],'Part 3 turns to Śiva: Kārtika Mondays and Karnataka’s great lamp festivals.','The Dāmodarāṣṭakam'),
 sources([('Text:','sanskritdocuments.org, “Satyavratokta Dāmodarastotram (Padma Purāṇa)”, ITRANS converted to IAST. Bhāgavata Purāṇa 10.9–10 (Yaśodā binds Kṛṣṇa; Yamalārjuna).')],'the extra verse found in popular editions; verse numbering differs between editions.','Verses numbered 1–7 for the hymn proper.')]
build(i,'PART 2 OF 7 · THE ROPE OF LOVE · VERSE BY VERSE',COV,'Bound by his mother, bound by love','First <b>the story</b> of Yaśodā and the rope, then <b>every verse</b> of Satyavrata’s hymn with its meaning, and how it is <b>sung in Kārtika</b>.','The Dāmodarāṣṭakam of the Padma Purāṇa, verse by verse in IAST with meanings: the story of Yaśodā binding Kṛṣṇa, the two arjuna trees, and singing the hymn with a lamp in Kārtika. Part 2 of the illustrated Kārtika series.',pp)
# ---------- Part 3
i=2
COV=covart('A Śiva liṅga surrounded by tiers of thousands of tiny lamps at a temple at night',g(220,190,1.6,'<path d="M-30 0 h60 l-6 -10 h-48z" fill="#8a8f9a"/><path d="M-14 -10 v-36 q14 -14 28 0 v36z" fill="#3a3a40"/>')+''.join(g(220,196-r*22,1,lamps_row(10-r,360-r*60)) for r in range(4)).replace('translate(0','translate(0'))
pp=[foreword(i,['Kārtika belongs to Śiva too. Its Mondays, the <b>Kārtika Somavāras</b>, are kept with fasting and worship in Śiva temples, and through the month temples across Karnataka light thousands of lamps in <b>dīpotsavas</b>, lamp festivals.','The greatest of them is the <b>Lakṣa Dīpotsava</b>, the festival of a hundred thousand lamps, held at Dharmasthaḷa and at many other temples.'],[('z','Why Monday?'),('b','Monday is Soma’s day, the moon’s day, and Śiva wears the moon. Kārtika’s Mondays are the holiest of all.')]),
 glance([('Somavāra','Monday, Soma’s (the moon’s) day, sacred to Śiva'),('Kārtika Somavāra','Each Monday of Kārtika: fasting, abhiṣeka, lamps'),('Lakṣa dīpa','“A hundred thousand lamps”, lit at temples'),('Where','Śiva temples across Karnataka; famously Dharmasthaḷa'),('Other days','Kārtika Pūrṇimā (Part 7); Kārttikai Dīpam (Part 4)')],svg(560,140,'A crescent moon above a liṅga',g(280,130,1.4,'<path d="M-14 0 v-36 q14 -14 28 0 v36z" fill="#3a3a40"/>')+g(280,30,1.4,moon()))),
 reading('mondays','ŚIVA’S MONDAYS','Kārtika Somavāra',svg(560,170,'Water poured over a liṅga from a pot, with bilva leaves',g(280,160,1.4,'<path d="M-30 0 h60 l-6 -10 h-48z" fill="#8a8f9a"/><path d="M-14 -10 v-36 q14 -14 28 0 v36z" fill="#3a3a40"/>')+g(320,70,1,pot('#c9a24a'))+'<path d="M310 80 q-10 20 -24 30" stroke="#8fb8de" stroke-width="4" fill="none"/>'),['<b>Moon’s day.</b> Monday (Somavāra) is named after Soma, the moon, whom Śiva wears in his hair.','<b>The vow.</b> On the Mondays of Kārtika devotees fast till evening, bathe the liṅga with water or milk (abhiṣeka), offer bilva leaves and light lamps.','<b>Popular story.</b> The Skanda Purāṇa’s Kārtika praise includes stories of devotees blessed for keeping these Mondays; families remember them as they fast.','<b>In temples.</b> Kārtika Mondays see the biggest crowds in Śiva temples across the south.'],[('z','Can I just light a lamp?'),('b','A lamp at a Śiva shrine on a Kārtika Monday is already the vow.')],'Kārtika Mondays: <b>water, bilva and lamps for Śiva</b>.'),
 reading('laksha','THE LAKṢA DĪPOTSAVA','A hundred thousand lamps',svg(560,190,'A temple courtyard with tiers of lamp stands blazing at night','<rect width="560" height="190" fill="#2a2a3a"/>'+''.join(g(280,180-r*28,1,lamps_row(14-r*2,520-r*70)) for r in range(5))),['<b>The name.</b> <i>Lakṣa</i> is a hundred thousand: lamps beyond counting set out on walls, steps and stands, lit together at dusk.','<b>Dharmasthaḷa.</b> The Lakṣa Dīpotsava at Dharmasthaḷa, home of Śrī Mañjunātha, is among Karnataka’s best known, with a procession of the deity and a gathering of scholars. Our <a href="/tulunadu/">Tulu Nadu collection</a> visits the temple.','<b>Everywhere.</b> Many temples, large and small, hold their own dīpotsava in Kārtika, often on a Monday or the full moon.','<b>Taking part.</b> Devotees bring oil and wicks, or sponsor a set of lamps, as their offering.'],[('z','Who lights them all?'),('b','Everyone. That’s the beauty: a whole town lighting lamps together.')],'Lamps beyond counting: <b>the Lakṣa Dīpotsava</b>.'),
 reading('lightmeaning','WHY LIGHT FOR ŚIVA','The column of fire',svg(560,190,'A column of fire rising beyond sight, with a swan flying up and a boar digging down',g(280,180,1,pillar_fire())+g(200,60,.6,'<path d="M-20 0 q10 -16 30 -10 l14 -10 v8 q-10 20 -44 12z" fill="#fff" stroke="#111" stroke-width="2"/>')+g(360,175,.6,beast('buffalo','#5a3a2a'))),['<b>The endless flame.</b> The Purāṇas tell how Brahmā and Viṣṇu once argued over who was greater, and a column of fire appeared between them. Brahmā flew up as a swan and Viṣṇu dug down as a boar, but neither found its end. Śiva appeared from it: <b>Liṅgodbhava</b>.','<b>Light as Śiva.</b> The lamps of Kārtika echo this endless light, most of all in the Kārttikai Dīpam at Tiruvaṇṇāmalai ('+L(3,'Part 4')+').','<b>Inner light.</b> Many read the lamp as the light of awareness, which is Śiva.','<b>Our series.</b> See also our <a href="/temples-of-india/pancha-bhuta-sthalas/">Pañcabhūta Sthalas</a>, where Tiruvaṇṇāmalai is the temple of fire.'],[('z','Even Brahmā and Viṣṇu couldn’t find the end?'),('b','That is the point: the light is infinite. Our little lamps are bows to it.')],'Kārtika’s lamps echo <b>the endless column of fire</b>.'),
 end(i,['<b>Mondays.</b> Kārtika Somavāras: fasting, abhiṣeka, bilva and lamps.','<b>Lamps.</b> Dīpotsavas across Karnataka.','<b>Lakṣa.</b> A hundred thousand lamps, famously at Dharmasthaḷa.','<b>Story.</b> The column of fire, Liṅgodbhava.','<b>Meaning.</b> Light as Śiva.'],'Part 4 goes to Tiruvaṇṇāmalai, where a great flame is lit on the hilltop each Kārtika full moon.','Kārtika Somavāras'),
 sources([('Customs:','Wikipedia, “Kartika (month)”, “Dharmasthala” (Lakṣa Dīpotsava); Śiva Purāṇa, Vidyeśvara Saṃhitā (column of fire).')],'the Skanda Purāṇa Somavāra stories (retold variously); details of particular temples’ festivals.','No dates or timings given.')]
build(i,'PART 3 OF 7 · MONDAYS · LAMPS · ŚIVA',COV,'A hundred thousand lamps','Śiva’s <b>Kārtika Mondays</b>, the <b>Lakṣa Dīpotsava</b> of Karnataka’s temples, and <b>why light</b> is offered to Śiva.','Kārtika Somavāras and the Lakṣa Dīpotsava: Śiva’s Mondays in Kārtika, temple lamp festivals in Karnataka including Dharmasthaḷa, and the column-of-fire story behind light offered to Śiva. Part 3 of the illustrated Kārtika series.',pp)
# ---------- Part 4
i=3
COV=covart('A great flame blazing on top of the Aruṇācala hill at night, with a temple tower below and lamps in every home',
 '<rect width="440" height="196" fill="#2a2a3a"/>'+g(220,190,1.6,hill_flame())+g(90,196,.6,'<path d="M-30 0 h60 l-10 -90 h-40z" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+g(330,196,1,lamps_row(4,160)))
pp=[foreword(i,['On the full-moon day of the Tamil month Kārttikai, as dusk falls, a huge flame is lit on the summit of the hill <b>Aruṇācala</b> at <b>Tiruvaṇṇāmalai</b>. Thousands cry “Aṇṇāmalaiyārukku arōharā!” and every home in Tamil Nadu lights rows of lamps. This is <b>Kārttikai Dīpam</b>.','It is the festival of Śiva as fire, the column of light of '+L(2,'Part 3')+', made visible on a hill.'],[('z','A fire on a mountain top?'),('b','A beacon seen for miles. The hill itself is worshipped as Śiva, and the flame shows him.')]),
 glance([('Name','Kārttikai Dīpam (Tamil), Kārtika Dīpa'),('When','The Kṛttikā (Kārttikai) star with the full moon of Kārttikai (Nov–Dec)'),('Where','Tiruvaṇṇāmalai, Tamil Nadu; and homes across the south'),('Deity','Śiva as Aruṇācaleśvara, the fire-liṅga'),('The flame','Mahā Dīpam, lit on the hilltop at dusk'),('Also','Bharaṇī Dīpam in the temple at dawn; lamps in every home')],svg(560,150,'The hill with the flame',g(280,145,1.2,hill_flame()))),
 reading('hill','ARUṆĀCALA','The hill that is Śiva',svg(560,180,'The Aruṇācala hill with the great temple at its foot and pilgrims walking around it',g(280,170,2,'<path d="M-90 0 L0 -70 L90 0z" fill="#8a7a5a"/>')+g(140,170,.7,'<path d="M-30 0 h60 l-10 -90 h-40z" fill="#e8c06a"/>')+''.join(g(x,174,.4,person(c)) for x,c in [(380,'#c0392b'),(410,'#1d6fb8'),(440,'#e0a800')])),['<b>A hill worshipped.</b> At Tiruvaṇṇāmalai the hill <b>Aruṇācala</b>, “the red mountain”, is itself worshipped as Śiva. It is the fire-element temple among the <a href="/temples-of-india/pancha-bhuta-sthalas/">Pañcabhūta Sthalas</a>.','<b>Girivalam.</b> Pilgrims walk around the hill barefoot (girivalam, about 14 km), especially on full-moon nights.','<b>The temple.</b> The great Aruṇācaleśvara temple at its foot is one of the largest in India.','<b>Saints.</b> The hill is linked with many saints, in modern times with Ramaṇa Maharṣi, who lived on it for decades.'],[('z','People walk around a whole mountain?'),('b','Barefoot, at night, by the thousand. It is one of the great pilgrimages of the south.')],'Aruṇācala: <b>a hill that is Śiva</b>.'),
 story('fire','THE STORY OF THE FLAME','Brahmā, Viṣṇu and the column of fire',strip('Three panels: Brahmā and Viṣṇu arguing; a column of fire between them; Śiva appearing from the fire',[panel([(god('#c0392b'),.8),(vishnu(),.6)],'#fff3cf',140),panel([(pillar_fire(),.9)],'#2a2a3a',None),panel([(shiva(),.9)],'#dfe9f6',140)],['who is greater?','the endless flame','Śiva appears']),'Tiruvaṇṇāmalai’s own story places the column of fire here.',['Brahmā and Viṣṇu argued over which of them was the greater.','A boundless column of fire appeared between them, without beginning or end.','Brahmā became a swan and flew up to find its top; Viṣṇu became a boar and dug down to find its base. Both failed.','Śiva appeared from the fire and humbled their pride. At their prayer, the fire cooled into the hill Aruṇācala.','On Kārttikai Dīpam the flame on the hilltop recalls that column of light.'],[('z','Brahmā lied in some versions, didn’t he?'),('b','In some tellings Brahmā claims he reached the top, with the ketakī flower as false witness, and is punished. Tellings differ; the flame is the point.')],'The endless fire, <b>now a hill and a beacon</b>.'),
 reading('mahadeepam','THE GREAT FLAME','How the Mahā Dīpam is lit',svg(560,190,'Lamps being lit in the temple at dawn, and the great cauldron flame on the hill at dusk','<rect width="560" height="190" fill="#2a2a3a"/>'+g(140,180,1,lamps_row(5,200))+g(420,180,1.3,hill_flame())+lab(140,150,'Bharaṇī Dīpam, dawn',11)+lab(420,60,'Mahā Dīpam, dusk',11)),['<b>At dawn.</b> Early on the day, the <b>Bharaṇī Dīpam</b> is lit in the temple sanctum, and five lamps are said to represent Śiva’s five aspects.','<b>At dusk.</b> In the evening the flame is carried, and at the moment of dusk the <b>Mahā Dīpam</b> is lit in a huge cauldron of ghee on the summit, visible for miles.','<b>Ardhanārīśvara.</b> As the flame is lit, the image of Ardhanārīśvara, Śiva who is half Pārvatī, is brought out briefly before the crowds.','<b>Days of light.</b> The hilltop flame is kept burning for several days.'],[('z','How big is the flame?'),('b','Big enough to be seen from far across the plain. People wait all day just to see it catch.')],'Dawn lamps in the temple, <b>dusk flame on the hill</b>.'),
 reading('homes','LAMPS IN EVERY HOME','Kārttikai in South Indian homes',svg(560,170,'A house doorway with rows of small clay lamps on the steps and wall',ground(560,170,150)+'<rect x="220" y="40" width="120" height="110" fill="#8a5a3a" stroke="#111" stroke-width="2"/>'+g(280,150,1,lamps_row(10,520))+g(280,40,1,lamps_row(6,300))),['<b>Agal viḷakku.</b> In Tamil homes, rows of little clay lamps (agal) line doorways, walls and steps on Kārttikai evening, often brighter than at Dīpāvalī.','<b>Kārttikai pori.</b> Sweet puffed-rice balls and appams are prepared and offered.','<b>In Karnataka.</b> Many Karnataka homes and temples light lamps on the same full moon as part of Kārtika Pūrṇimā ('+L(6,'Part 7')+').','<b>Kṛttikā and Murugan.</b> The Kṛttikā stars are the six mothers who nursed Skanda; the festival is also sacred to Murugan. See our <a href="/subramanya/">Subrahmaṇya series</a>.'],[('z','Brighter than Dīpāvalī?'),('b','In many Tamil homes, yes. Kārttikai is their festival of lamps.')],'Every doorway lit: <b>Kārttikai in the home</b>.'),
 end(i,['<b>When.</b> The Kṛttikā star with the Kārttikai full moon.','<b>Where.</b> Tiruvaṇṇāmalai, where the hill Aruṇācala is Śiva.','<b>Story.</b> The endless column of fire became the hill.','<b>Flames.</b> Bharaṇī Dīpam at dawn, Mahā Dīpam on the summit at dusk.','<b>Homes.</b> Rows of clay lamps across the south.'],'Part 5 turns to Tulasī, the sacred plant in the courtyard, and her story.','Kārttikai Dīpam'),
 sources([('Festival:','Wikipedia, “Karthikai Deepam”, “Annamalaiyar Temple”, “Arunachala”; Śiva Purāṇa (column of fire).')],'the length of the girivalam path (commonly 14 km); details of the temple ritual sequence.','No dates or timings given.')]
build(i,'PART 4 OF 7 · ARUṆĀCALA · THE GREAT FLAME',COV,'The beacon on the red mountain','The hill <b>Aruṇācala</b>, the <b>story of the endless fire</b>, how the <b>great flame</b> is lit, and lamps in every home.','Kārttikai Dīpam at Tiruvaṇṇāmalai: the Aruṇācala hill as Śiva, the column-of-fire story, the Bharaṇī and Mahā Dīpam, and Kārttikai lamps in South Indian homes. Part 4 of the illustrated Kārtika series.',pp)
# ---------- Part 5 Tulasī
i=4
COV=covart('A tulasī plant in a decorated square pedestal (tulasī kaṭṭe) in a courtyard, with a lamp and a woman circling it',ground(440,220,190,'#e9d6c0')+g(220,196,1.6,tulasi())+g(150,190,1.2,lamp())+g(320,196,1,person('#c0392b')))
pp=[foreword(i,['In countless Hindu homes, a small square pedestal in the courtyard or on the balcony holds a <b>tulasī</b> (holy basil) plant. It is watered, circled and given a lamp every evening. In Karnataka it is the <b>tulasī kaṭṭe</b>, in Tamil the <b>tulasī māḍam</b>.','Tulasī is a plant and a goddess. This part tells her story and her worship; '+L(5,'Part 6')+' tells her wedding to Viṣṇu.'],[('z','A plant is a goddess?'),('b','The tradition sees the Goddess in her. Her leaves go to Viṣṇu in every pūjā.')]),
 glance([('Plant','Tulasī, holy basil (Ocimum tenuiflorum)'),('Goddess','Tulasī Devī, also Vṛndā; dear to Viṣṇu'),('Kinds','Rāma tulasī (green) and Kṛṣṇa tulasī (purple)'),('At home','Tulasī kaṭṭe (Kannada), tulasī māḍam (Tamil), tulasī vṛndāvan'),('Use','Leaves offered to Viṣṇu and Kṛṣṇa; beads (tulasī mālā)'),('Great days','Tulasī Vivāha (Kārtika), daily evening lamp')],svg(560,150,'Two tulasī plants, green and purple',g(200,145,1.2,tulasi())+g(360,145,1.2,tulasi().replace('#3a8a3a','#6a3a7a')))),
 story('vrinda','THE STORY OF VṚNDĀ','One telling from the Purāṇas',strip('Three panels: the faithful wife Vṛndā praying; Jalandhara fighting the gods; Vṛndā’s body becoming the tulasī plant',[panel([(person('#c0392b'),1),(lamp(),.9)],'#fff3cf',140),panel([(demon('#2a6a3a'),.9),(god(),.6)],'#e9e3f5',140),panel([(tulasi(),1)],'#cfe0b8',140)],['Vṛndā’s devotion','Jalandhara at war','she becomes tulasī']),'Tellings differ between the Purāṇas; this is a widely told one.',['<b>Vṛndā</b> was the devoted wife of the powerful demon king <b>Jalandhara</b>. Her chastity and devotion made him invincible.','Jalandhara fought the gods, and even Śiva could not defeat him while Vṛndā’s virtue protected him.','To break that protection, Viṣṇu took Jalandhara’s form and came to Vṛndā; her vow was broken, and Jalandhara fell.','Learning the truth, Vṛndā cursed Viṣṇu to become a stone, the <b>śālagrāma</b>, and gave up her life.','Moved, Viṣṇu blessed her: she would become the <b>tulasī</b> plant, dearest to him, and he would marry her every year as the śālagrāma: Tulasī Vivāha.'],[('z','Viṣṇu tricked her? That’s not nice.'),('b','The tradition doesn’t hide it. Viṣṇu accepts her curse and honours her above all plants. The story turns a wrong into reverence.')],'A faithful wife wronged, <b>honoured for ever as tulasī</b>.'),
 reading('worship','WORSHIPPING TULASĪ','The kaṭṭe and the evening lamp',svg(560,180,'A woman watering the tulasī in its pedestal and placing a lamp',ground(560,180,160,'#e9d6c0')+g(280,160,1.4,tulasi())+g(180,160,1,person('#c0392b'))+g(200,110,.8,pot('#c9a24a'))+g(360,150,1,lamp())),['<b>Morning water.</b> After the bath, water is offered to the tulasī with a prayer.','<b>Evening lamp.</b> At dusk a lamp is placed at the kaṭṭe, and the plant is circled (pradakṣiṇa), often three times.','<b>Not on certain days.</b> Many families do not pluck leaves on Ekādaśī, Dvādaśī or after sunset; customs differ.','<b>In Kārtika.</b> The worship is especially devoted in Kārtika, leading to Tulasī Vivāha.'],[('z','Why not pick leaves on Ekādaśī?'),('b','Family customs say she too is fasting that day. Pick the day before.')],'Water in the morning, <b>a lamp at dusk</b>.'),
 reading('leaves','LEAVES FOR VIṢṆU','Why tulasī goes in every offering',svg(560,160,'A plate of food with a single tulasī leaf on top, offered before Viṣṇu',g(200,140,1.3,'<ellipse rx="50" ry="12" fill="#e8c06a"/><ellipse cy="-8" rx="8" ry="4" fill="#3a8a3a"/>')+g(400,150,1,vishnu())),['<b>No offering without it.</b> In Vaiṣṇava worship, food is offered to Viṣṇu or Kṛṣṇa with a tulasī leaf on it; without the leaf, it is said, he does not accept it.','<b>Tulasī mālā.</b> Rosaries of tulasī wood are worn and used for japa by Vaiṣṇavas.','<b>Kṛṣṇa’s weight.</b> A popular story tells how Satyabhāmā could not balance Kṛṣṇa on a scale with all her gold, but Rukmiṇī did it with one tulasī leaf placed with love.','<b>Not for Gaṇeśa.</b> By a common tradition, tulasī is not offered to Gaṇeśa; customs vary for Śiva.'],[('z','One leaf outweighed all the gold?'),('b','A leaf with love is heavier than gold without it. That is the whole teaching.')],'One leaf, <b>offered with love</b>.'),
 reading('plant','THE PLANT ITSELF','Holy basil',svg(560,160,'A close-up of tulasī leaves and flower spikes',g(280,150,2,tulasi())),['<b>Holy basil.</b> Tulasī is <i>Ocimum tenuiflorum</i>, a fragrant basil native to India.','<b>Two colours.</b> Green-leaved Rāma tulasī and purple-leaved Kṛṣṇa tulasī are the common kinds.','<b>Traditional medicine.</b> It has long been used in Āyurveda and home remedies, especially for coughs and colds; anyone with a health condition should seek medical advice rather than relying on it.','<b>Easy to grow.</b> It grows well in a pot in sun, which is partly why every home can have one.'],[('z','So tulasī is just basil?'),('b','Botanically, a basil. In the home, much more.')],'A fragrant basil, <b>a goddess in the courtyard</b>.'),
 end(i,['<b>Plant.</b> Holy basil, in a kaṭṭe in the courtyard.','<b>Story.</b> Vṛndā, wronged, became tulasī; Viṣṇu became the śālagrāma.','<b>Worship.</b> Water at morning, a lamp and circling at dusk.','<b>Leaves.</b> Offered with every food to Viṣṇu; one leaf outweighs gold.','<b>Kārtika.</b> Her month, ending in her wedding.'],'Part 6 is the wedding: Prabodhinī Ekādaśī, Viṣṇu’s waking, and Tulasī Vivāha.','Tulasī'),
 sources([('Story:','Wikipedia, “Tulsi Vivah”, “Vrinda (goddess)”, “Jalandhara” (Śiva and Padma Purāṇa tellings); Satyabhāmā’s tulābhāra (popular story).'),('Plant:','Wikipedia, “Ocimum tenuiflorum”.')],'variant tellings of the Vṛndā story; family rules on plucking leaves.','Stories retold; tellings differ.')]
build(i,'PART 5 OF 7 · THE PLANT · THE GODDESS',COV,'The tulasī kaṭṭe','Who <b>Tulasī</b> is, the <b>story of Vṛndā</b>, how she is <b>worshipped</b> at home, why her <b>leaves</b> go to Viṣṇu, and the plant itself.','Tulasī, the sacred holy basil: the story of Vṛndā and Jalandhara, the tulasī kaṭṭe and its daily worship, why tulasī leaves are offered to Viṣṇu, and the plant itself. Part 5 of the illustrated Kārtika series.',pp)
# ---------- Part 6
i=5
COV=covart('A tulasī plant dressed as a bride with a small red sari and bangles, beside a śālagrāma stone on a decorated platform, with a wedding canopy of sugarcane',g(220,196,1.3,'<path d="M-90 0 v-120 M90 0 v-120 M-100 -120 h200" stroke="#5a8a3a" stroke-width="6" fill="none"/>')+g(180,196,1.3,tulasi())+g(270,190,1.2,'<ellipse rx="16" ry="12" fill="#2a2a3a"/>')+g(330,196,1.1,lamp()))
pp=[foreword(i,['Since Devaśayanī Ekādaśī in Āṣāḍha, Viṣṇu has slept. On <b>Prabodhinī Ekādaśī</b>, in the bright half of Kārtika, he wakes, and the first thing he does is get married: to <b>Tulasī</b>.','This is <b>Tulasī Vivāha</b>, a full wedding celebrated in courtyards across India, after which the human wedding season begins. Our <a href="/festivals/ekadashi/kartika/">Ekādaśī series</a> tells Prabodhinī’s story; here is the wedding.'],[('z','A wedding between a plant and a stone?'),('b','Between the Goddess and the Lord, in those forms. And families celebrate it like their own daughter’s wedding.')]),
 glance([('Prabodhinī','Bright Ekādaśī of Kārtika: Viṣṇu wakes; Cāturmāsya ends'),('Tulasī Vivāha','On Prabodhinī or the next days (often Dvādaśī; up to the full moon in some regions)'),('Bride','Tulasī, dressed in a sari with ornaments'),('Groom','Viṣṇu as śālagrāma, or Kṛṣṇa’s image'),('Canopy','Often sugarcane stalks'),('After','The wedding season opens'),('In Karnataka','Often on Dvādaśī: “Tulasī Habba”, with amla and tamarind branches')],svg(560,150,'Tulasī and the śālagrāma side by side',g(240,145,1.2,tulasi())+g(330,140,1.2,'<ellipse rx="16" ry="12" fill="#2a2a3a"/>'))),
 reading('wake','VIṢṆU WAKES','Prabodhinī Ekādaśī',svg(560,170,'Viṣṇu sitting up from the serpent bed, a conch being blown and bells rung',g(240,150,1,sheshashayi())+g(420,130,1.4,conch())+g(480,130,1.4,bell())),['<b>Four months’ sleep ends.</b> Since <b>Devaśayanī Ekādaśī</b> in Āṣāḍha, Viṣṇu has slept on Śeṣa in the ocean of milk. On <b>Prabodhinī</b> (also Utthāna or Devutthāna) Ekādaśī he is woken with conch, bells and songs.','<b>Cāturmāsya ends.</b> The vows of the rainy season are completed, and ascetics may travel again.','<b>Waking songs.</b> Temples sing waking hymns; homes draw his footprints in rice flour leading in.','<b>Paṇḍharpūr.</b> In Maharashtra, the Kārtikī Ekādaśī brings another great pilgrimage to Viṭṭhala.'],[('z','What does God do when he wakes?'),('b','Gets married, of course! The wedding follows at once.')],'Viṣṇu wakes; <b>the season of vows ends</b>.'),
 story('wedding','THE WEDDING','How Tulasī Vivāha is celebrated',strip('Three panels: decorating the tulasī as a bride; the śālagrāma brought as the groom; the couple circled with lamps',[panel([(tulasi(),1),(person('#c0392b'),.7)],'#fde4e4',140),panel([('<ellipse rx="16" ry="12" fill="#2a2a3a"/>',1.4),(person('#1d6fb8'),.7)],'#dfe9f6',140),panel([(tulasi(),.8),('<ellipse rx="14" ry="10" fill="#2a2a3a"/>',1),(lamp(),.8)],'#fff3cf',140)],['the bride is dressed','the groom arrives','the wedding']),'Each family does it its own way; the shape is a real Hindu wedding.',['The tulasī kaṭṭe is cleaned and painted, and the plant dressed as a bride: a small sari, bangles, a necklace, kuṅkuma.','A wedding canopy (maṇṭapa) is made, often of sugarcane stalks.','Viṣṇu comes as the groom, as the <b>śālagrāma</b> stone or an image of Kṛṣṇa, often brought by the “groom’s side” of the family.','The rites of a wedding follow: the sacred thread, the giving of the bride, circling (and in some homes the seven steps), with songs.','Sweets are shared, and the human wedding season begins.'],[('z','Who “gives away” the bride?'),('b','Often the family that tends the tulasī, as her parents. Some couples without daughters do it to know the joy of giving a daughter in marriage.')],'Tulasī weds Viṣṇu: <b>the first wedding of the season</b>.'),
 reading('karnataka','TULASĪ HABBA IN KARNATAKA','Amla, tamarind and lamps',svg(560,170,'A tulasī kaṭṭe decorated with gooseberry and tamarind branches and many lamps',ground(560,170,150,'#e9d6c0')+g(280,150,1.4,tulasi())+g(180,150,.8,gooseberry())+g(380,150,.8,tree('#6a8a3a'))+g(280,150,1,lamps_row(7,400))),['<b>Uttāna Dvādaśī.</b> In much of Karnataka the festival is kept on the Dvādaśī after Prabodhinī, often called Tulasī Habba or Uttāna Dvādaśī.','<b>Branches.</b> Branches of the <b>āmalaka</b> (gooseberry) and sometimes tamarind are placed in the kaṭṭe beside the tulasī, representing Viṣṇu.','<b>Lamps.</b> Lamps are lit around the kaṭṭe in the evening, many of them, like a small dīpotsava.','<b>Fireworks.</b> In some families it is a second, smaller Dīpāvalī, with crackers and sweets.'],[('z','Why the gooseberry branch?'),('b','The āmalakī tree is dear to Viṣṇu, as in Āmalakī Ekādaśī. Here it stands in for him.')],'Karnataka’s Tulasī Habba: <b>gooseberry, lamps and joy</b>.'),
 reading('season','THE WEDDING SEASON BEGINS','Why marriages wait',svg(560,160,'A wedding canopy and a couple, with a calendar page turning',g(200,150,1.2,'<path d="M-60 0 v-90 M60 0 v-90 M-70 -90 h140" stroke="#5a8a3a" stroke-width="6" fill="none"/>')+g(180,150,1,person('#1d6fb8'))+g(220,150,1,person('#c0392b'))+g(420,120,1.2,'<rect x="-30" y="-40" width="60" height="70" fill="#fff" stroke="#111" stroke-width="2"/><path d="M30 -40 l-20 20 v50" fill="#dfe9f6" stroke="#111"/>')),['<b>No weddings while the Lord sleeps.</b> By tradition, Hindu weddings are not held during Cāturmāsya, the months of Viṣṇu’s sleep.','<b>Tulasī first.</b> Once he wakes and weds Tulasī, the auspicious season for human weddings opens.','<b>Regional calendars.</b> Exact rules depend on the region and almanac; astrologers set the actual wedding dates.','<b>A family festival.</b> For many, Tulasī Vivāha is a rehearsal of joy for the weddings to come.'],[('z','So weddings are seasonal?'),('b','Largely. The calendar of the Lord’s sleep and waking shapes the calendar of human marriages.')],'After Tulasī’s wedding, <b>everyone else’s can begin</b>.'),
 end(i,['<b>Waking.</b> Prabodhinī Ekādaśī ends Viṣṇu’s four-month sleep.','<b>Bride.</b> Tulasī, dressed in a sari.','<b>Groom.</b> Viṣṇu as śālagrāma or Kṛṣṇa.','<b>Karnataka.</b> Tulasī Habba on Dvādaśī with gooseberry branches and lamps.','<b>After.</b> The wedding season opens.'],'Part 7 closes the month: Kārtika Pūrṇimā, Śiva’s victory over the three cities and the river of lamps at Vārāṇasī.','Prabodhinī and Tulasī Vivāha'),
 sources([('Festival:','Wikipedia, “Tulsi Vivah”, “Prabodhini Ekadashi”, “Chaturmasya”.')],'the exact day of Tulasī Vivāha (varies by region from Ekādaśī to Pūrṇimā); Karnataka customs vary by family.','Customs described in common forms.')]
build(i,'PART 6 OF 7 · VIṢṆU WAKES · TULASĪ WEDS',COV,'The bride in the courtyard','<b>Viṣṇu wakes</b> on Prabodhinī, then <b>the wedding</b> step by step, Karnataka’s <b>Tulasī Habba</b>, and why it opens the <b>wedding season</b>.','Prabodhinī Ekādaśī and Tulasī Vivāha: Viṣṇu wakes from Cāturmāsya, the wedding of Tulasī and the śālagrāma, Tulasī Habba in Karnataka, and the start of the wedding season. Part 6 of the illustrated Kārtika series.',pp)
# ---------- Part 7
i=6
COV=covart('Śiva with a bow shooting a fiery arrow at three flying cities, and below, lamps floating on a river',g(110,150,1,shiva())+g(150,110,.8,bow())+''.join(g(x,y,.4,palace()) for x,y in [(300,60),(360,90),(410,50)])+'<path d="M160 100 L290 60" stroke="#ff8c1a" stroke-width="3"/>'+river(440,175)+''.join(g(x,190,1,boat_lamp()) for x in range(40,440,50)))
pp=[foreword(i,['The month ends in a full moon of light. <b>Kārtika Pūrṇimā</b> celebrates Śiva as <b>Tripurāri</b>, destroyer of the three demon cities, and in Vārāṇasī it is <b>Dev Dīpāvalī</b>, “the gods’ Dīpāvalī”, when the ghāṭs of the Gaṅgā blaze with lamps.','It is also remembered as the day of Viṣṇu’s first avatāra, Matsya, and in many places as the climax of the month’s lamp-offering.'],[('z','Another Dīpāvalī?'),('b','The gods’ own, the story goes: they come down to bathe in the Gaṅgā and light lamps for Śiva’s victory.')]),
 glance([('When','Full moon of Kārtika (November)'),('Names','Kārtika Pūrṇimā, Tripurārī Pūrṇimā, Dev Dīpāvalī'),('Śiva','Tripurāri: destroyer of the three cities'),('Viṣṇu','Matsya Jayantī: the fish avatāra'),('Vārāṇasī','Dev Dīpāvalī: lamps on all the ghāṭs'),('Customs','River bathing, lamps floated on water, temple lamps')],svg(560,140,'A full moon over a river with floating lamps',river(560,90)+g(280,40,1,'<circle r="26" fill="#fff8d0" stroke="#111" stroke-width="2"/>')+''.join(g(x,120,1,boat_lamp()) for x in range(40,560,60)),bg='#2a2a3a')),
 story('tripura','TRIPURĀRI','Śiva and the three cities',strip('Three panels: three flying fortresses of gold, silver and iron; Śiva on a chariot made of the gods; one arrow burning all three',[panel([(palace(),.25),(palace(),.25),(palace(),.25)],'#e9e3f5',90),panel([(shiva(),.7)],'#dfe9f6',140),panel([(flames(),1.2)],'#2a2a3a',150)],['three flying cities','the cosmic chariot','one arrow']),'This victory is told in the Mahābhārata and the Śiva Purāṇa.',['Three demon brothers, sons of Tāraka, built three flying cities of gold, silver and iron, which could be destroyed only by a single arrow when all three lined up.','From their cities they tormented the worlds.','The gods built Śiva a chariot of the whole cosmos: the earth its body, sun and moon its wheels, Mount Meru his bow, Viṣṇu his arrow.','When the three cities came into line, Śiva loosed the one arrow and burnt them all.','He became <b>Tripurāri</b>, “enemy of the three cities”; the gods lit lamps in joy on the full moon of Kārtika.'],[('z','Viṣṇu was the arrow?'),('b','In the telling, yes: all the gods became parts of Śiva’s weapon. A whole universe working together.')],'One arrow, three cities: <b>Śiva as Tripurāri</b>.'),
 reading('devdipavali','DEV DĪPĀVALĪ AT VĀRĀṆASĪ','The gods’ festival of lamps',svg(560,190,'The ghāṭs of Vārāṇasī as steps down to the Gaṅgā, every step lined with lamps','<rect width="560" height="190" fill="#2a2a3a"/>'+''.join(f'<rect x="0" y="{40+k*20}" width="560" height="20" fill="#8a7a5a" stroke="#111" stroke-width="1"/>' for k in range(5))+''.join(g(280,58+k*20,1,lamps_row(14,540)) for k in range(5))+river(560,150)),['<b>Lamps on every step.</b> On Kārtika Pūrṇimā the ghāṭs of <b>Vārāṇasī</b> are lined with clay lamps from end to end, a sight that draws visitors from across the world.','<b>The story.</b> Tradition says the gods descend to Kāśī to bathe in the Gaṅgā and celebrate Śiva’s victory over Tripura with lamps.','<b>Gaṅgā ārati.</b> The evening ārati at the ghāṭs is especially grand.','<b>Kāśī Viśvanātha.</b> Our <a href="/shiva/kashi-vishwanathashtakam/">Kāśī Viśvanāthāṣṭakam</a> sings of Kāśī’s Lord.'],[('z','The gods come to Kāśī?'),('b','That is the tradition. Seeing the ghāṭs that night, it is easy to believe.')],'Vārāṇasī’s ghāṭs ablaze: <b>Dev Dīpāvalī</b>.'),
 reading('matsya','MATSYA AND MORE','Other memories of the full moon',svg(560,170,'A great fish towing a boat through flood waters',river(560,90,'#5a8ac0')+g(200,110,1.4,'<path d="M-60 0 q30 -30 80 0 q-50 30 -80 0z" fill="#e0a800" stroke="#111" stroke-width="2"/><path d="M20 0 l20 -16 v32z" fill="#e0a800" stroke="#111" stroke-width="2"/>')+g(400,120,1.2,'<path d="M-40 0 h80 l-10 14 h-60z" fill="#8a5a2a" stroke="#111" stroke-width="2"/>')+'<path d="M240 110 L360 115" stroke="#111" stroke-width="2"/>'),['<b>Matsya.</b> Some traditions mark Kārtika Pūrṇimā as the day Viṣṇu took his first avatāra, <b>Matsya</b>, the fish who saved Manu and the Vedas from the flood. Our <a href="/vishnu/dashavatara/">Daśāvatāra series</a> tells it.','<b>Floating lamps.</b> In Odisha and elsewhere, little boats with lamps are floated on rivers and seas (Boita Bandāṇa), remembering ancient sea voyages.','<b>Bathing.</b> A dip in a holy river on this full moon is especially praised: at Puṣkar a great fair is held.','<b>Guru Nānak.</b> The Sikh community celebrates Guru Nānak’s birth (Gurpurab) on this full moon.'],[('z','So many things on one day!'),('b','Full moons gather festivals. This one gathers Śiva, Viṣṇu, rivers and lamps.')],'Matsya, river lamps, holy dips: <b>a full moon of many meanings</b>.'),
 reading('closing','CLOSING THE MONTH','From Kārtika to Mārgaśīrṣa',svg(560,150,'A last lamp burning as a crescent moon rises',g(200,130,1.6,lamp())+g(380,60,1.4,moon())),['<b>The last lamps.</b> Those who kept a lamp vow all month offer their final lamps and complete the vow with charity.','<b>Kārtika snāna ends.</b> The dawn bathing ends with a final bath on the full moon.','<b>Into winter.</b> Mārgaśīrṣa follows, the month Kṛṣṇa calls the best (Gītā 10.35), and with it Dhanurmāsa; see our <a href="/festivals/dhanurmasa/">Dhanurmāsa series</a>.','<b>The series.</b> Back to '+L(0,'Part 1')+' for the month, or to the <a href="/festivals/">festival calendar</a>.'],[('z','What do I do with my Kārtika vow now?'),('b','Finish it with a gift of food or a lamp to someone. Then carry one small habit forward.')],'The lamps of Kārtika <b>lead into winter’s light</b>.'),
 end(i,['<b>Full moon.</b> Kārtika Pūrṇimā ends the month.','<b>Śiva.</b> Tripurāri burnt the three cities with one arrow.','<b>Vārāṇasī.</b> Dev Dīpāvalī, lamps on every ghāṭ.','<b>Viṣṇu.</b> Remembered as Matsya’s day.','<b>Practice.</b> River bathing and floating lamps; the month’s vows completed.'],'That completes the Kārtika series. Back to '+L(0,'Part 1')+', or on to <a href="/festivals/dhanurmasa/">Dhanurmāsa</a>.','Kārtika Pūrṇimā'),
 sources([('Festival:','Wikipedia, “Kartik Purnima”, “Dev Deepawali”, “Tripurantaka”, “Matsya”. Mahābhārata, Karṇa Parva and Śiva Purāṇa, Rudra Saṃhitā (Tripura).')],'Matsya Jayantī’s date (some place it in Caitra); regional customs.','No dates or timings given.')]
build(i,'PART 7 OF 7 · TRIPURĀRI · DEV DĪPĀVALĪ',COV,'One arrow, a river of lamps','<b>Śiva burns the three cities</b>, Vārāṇasī’s <b>Dev Dīpāvalī</b>, Matsya and the river lamps, and <b>closing the month</b>.','Kārtika Pūrṇimā: Śiva as Tripurāri destroying the three cities, Dev Dīpāvalī at Vārāṇasī, Matsya Jayantī, floating lamps and river bathing, and closing the Kārtika month. Part 7 of the illustrated Kārtika series.',pp)
